        size: Int,
    ): List<DictionaryWithId> {
        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .query { q ->
                            q.bool { b ->
                                b.filter { f ->
                                    f.term { t ->
                                        t
                                            .field("type")
                                            .value { v -> v.stringValue(type.toString()) }
                                    }
                                }
                            }
                        }.from(page)
                        .size(size)
                        .sort(baseSortQuery())
                },
                Dictionary::class.java,
            )

        return response.hits().hits().mapNotNull { hit ->
            hit.id()?.let { id -> hit.source()?.let { DictionaryWithId(id, it) } }
        }
    }

    override fun findByWordAndType(
        word: String,
        type: Type,
        isMatch: Boolean,
    ): List<DictionaryWithId> {
        val shouldQuery =
            if (isMatch) {
                Query.of {
                    it.match { m ->
                        m.field("keyword")
                        m.query { q ->
                            q.stringValue(word)
                        }
                    }
                    it.match { m2 ->
                        m2.field("value")
                        m2.query { q2 ->
                            q2.stringValue(word)
                        }
                    }
                }
            } else {
                Query.of {
                    it.wildcard { w ->
                        w.field("keyword")
                        w.value("*$word*")
                    }
                    it.wildcard { w2 ->
                        w2.field("value")
